import unittest
from candidate import car_race_collision


class TestCarRaceCollision(unittest.TestCase):
    def test_n_zero_returns_zero(self):
        self.assertEqual(car_race_collision(0), 0)

    def test_n_one_returns_one(self):
        self.assertEqual(car_race_collision(1), 1)

    def test_n_two_returns_four(self):
        self.assertEqual(car_race_collision(2), 4)

    def test_n_three_returns_nine(self):
        self.assertEqual(car_race_collision(3), 9)

    def test_n_five_returns_twentyfive(self):
        self.assertEqual(car_race_collision(5), 25)

    def test_n_ten_returns_onehundred(self):
        self.assertEqual(car_race_collision(10), 100)

    def test_n_large_number_returns_square(self):
        self.assertEqual(car_race_collision(1000), 1000000)

    def test_n_hundred_returns_tenthousand(self):
        self.assertEqual(car_race_collision(100), 10000)

    def test_n_negative_returns_positive_square(self):
        self.assertEqual(car_race_collision(-3), 9)

    def test_n_negative_one_returns_one(self):
        self.assertEqual(car_race_collision(-1), 1)

    def test_n_negative_large_returns_positive_square(self):
        self.assertEqual(car_race_collision(-10), 100)

    def test_n_float_returns_float_square(self):
        self.assertAlmostEqual(car_race_collision(2.5), 6.25)

    def test_n_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            car_race_collision(None)

    def test_n_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            car_race_collision("3")

    def test_n_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            car_race_collision([1, 2, 3])

    def test_n_dict_raises_type_error(self):
        with self.assertRaises(TypeError):
            car_race_collision({"a": 1})

    def test_n_bool_true_returns_one(self):
        self.assertEqual(car_race_collision(True), 1)

    def test_n_bool_false_returns_zero(self):
        self.assertEqual(car_race_collision(False), 0)

    def test_result_type_is_int_for_int_input(self):
        self.assertIsInstance(car_race_collision(5), int)

    def test_n_15_returns_two_hundred_fifty(self):
        self.assertEqual(car_race_collision(15), 225)

    def test_n_50_returns_two_thousand_fifty(self):
        self.assertEqual(car_race_collision(50), 2500)


if __name__ == '__main__':
    unittest.main()
